<script setup lang="ts">
import DecimalInput from "../components/DecimalInput.vue"
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { useRoute, useRouter } from 'vue-router'
import { api, json, ApiError, canonicalJSON } from '../api'
import { emptyInput, type Product, type EvaluationRevision, type Competitor, type ProductImage } from '../types'
import { useApp } from '../stores/app'
import Icon from '../components/Icon.vue'
import CategorySelect from '../components/CategorySelect.vue'
import RateEditor from '../components/RateEditor.vue'
import ResearchFields from '../components/ResearchFields.vue'
import Results from '../components/Results.vue'
import ResearchInsights from '../components/ResearchInsights.vue'
const { t } = useI18n(); const route = useRoute(); const router = useRouter(); const app = useApp()
const input = ref(emptyInput()); const competitors = ref<Competitor[]>([]); const existingImages = ref<ProductImage[]>([]); const files = ref<{file: File; url: string}[]>([]); const version = ref(0); const step = ref(0); const evaluation = ref<EvaluationRevision>(); const calculating = ref(false); const saving = ref(false); const initialized = ref(false); const calculationError = ref(''); const localFields = ref<Record<string,string>>({}); let timer: ReturnType<typeof setTimeout> | undefined; let sequence = 0; const editing = computed(() => typeof route.params.id === 'string')
const reference = ref<{ url: string; name: string }>(); const removedImages = ref<string[]>([])
const visibleImages = computed(() => existingImages.value.filter(im => !removedImages.value.includes(im.id)))
const moneyFields = ['cost','price','fixed','packaging'] as const
const fresh = computed(() => evaluation.value && canonicalJSON(evaluation.value.input) === canonicalJSON(input.value))
async function calculate() { clearTimeout(timer); const token = ++sequence; calculating.value = true; try { const res = await api<EvaluationRevision>('/calculate', json('POST', input.value)); if (token === sequence) { evaluation.value = res; calculationError.value = ''; localFields.value = {} } } catch(e) { if (token === sequence) { calculationError.value = e instanceof Error ? e.message : String(e); localFields.value = e instanceof ApiError ? e.fields : {}; evaluation.value = undefined } } finally { if (token === sequence) calculating.value = false } }
watch(input, () => { if (!initialized.value) return; clearTimeout(timer); sequence++; timer = setTimeout(calculate, 350) }, { deep: true })
onMounted(async () => { try { if (!app.settings) await app.loadSettings(); if (editing.value) { const p = await api<Product>(`/products/${route.params.id}`); input.value = { ...p.input, overrides: p.input.overrides || {} }; competitors.value = p.competitors || []; existingImages.value = p.images; version.value = p.version } else input.value.targetMargin = app.settings?.targetMargin || '15'; initialized.value = true; await calculate() } catch(e) { app.report(e) } })
onUnmounted(() => { clearTimeout(timer); files.value.forEach(f => URL.revokeObjectURL(f.url)) })
function chooseImages(event: Event) { const chosen = Array.from((event.target as HTMLInputElement).files || []); if (chosen.length + files.value.length + visibleImages.value.length > 5 || chosen.some(f => f.size > 5 * 1024 * 1024 || !['image/jpeg','image/png','image/webp'].includes(f.type))) { app.report(new Error(t('invalidImage'))); return } chosen.forEach(file => files.value.push({file, url: URL.createObjectURL(file)})); (event.target as HTMLInputElement).value = '' }
function removeFile(i: number) { if (reference.value?.url === files.value[i].url) reference.value = undefined; URL.revokeObjectURL(files.value[i].url); files.value.splice(i,1) }
async function save() { if (!input.value.name.trim()) { app.report(new Error(t('basicError'))); app.fields = { name: t('required') }; step.value = 0; return } if (!fresh.value || saving.value) return; saving.value = true; app.clear(); try { let p = await api<Product>(editing.value ? `/products/${route.params.id}` : '/products', json(editing.value ? 'PUT' : 'POST', { version: version.value, input: input.value, competitors: competitors.value })); version.value = p.version; for (const id of removedImages.value) p = await api<Product>(`/products/${p.id}/images/${id}`, json('DELETE', { version: p.version })); let uploadFailed = false; for (const item of files.value) { const form = new FormData(); form.set('file', item.file); form.set('version', String(p.version)); try { p = await api<Product>(`/products/${p.id}/images`, { method:'POST', body: form }) } catch { uploadFailed = true; break } } await router.push(`/products/${p.id}`); if (uploadFailed) app.report(new Error(t('imageFailed'))); else app.success(t('savedSuccess')) } catch(e) { app.report(e) } finally { saving.value = false } }
function reloadPage() { window.location.reload() }
</script>
<template><div class="page-heading"><div><span class="eyebrow"><span class="eyebrow-line"></span>{{ t('research') }}</span><h1>{{ t('researchTitle') }}</h1><p>{{ t('researchSub') }}</p></div><RouterLink to="/" class="btn secondary"><Icon name="back" />{{ t('products') }}</RouterLink></div>
 <div class="research-toolbar"><div class="segment-control" role="tablist" :aria-label="t('research')"><button id="product-tab" role="tab" :aria-selected="step === 0" aria-controls="product-inputs" :class="{ chosen: step === 0 }" @click="step = 0">{{ t('financials') }}</button><button id="market-tab" role="tab" :aria-selected="step === 1" aria-controls="market-inputs" :class="{ chosen: step === 1 }" @click="step = 1">{{ t('market') }} <span v-if="competitors.length">({{ competitors.length }})</span></button></div><a class="text-link" href="#live-results">{{ t('viewResults') }}<Icon name="arrow" :size="16" /></a></div>
 <div class="calculator-layout research-layout"><div class="calculator-form"><div id="product-inputs" v-show="step === 0" role="tabpanel" aria-labelledby="product-tab">
 <section class="panel form-panel"><div class="section-title"><span class="section-icon"><Icon name="box" /></span><div><h3>{{ t('commercial') }}</h3><p>{{ t('commercialSub') }}</p></div></div><div class="form-grid"><div class="field"><label for="name">{{ t('name') }} <span class="required-dot">*</span></label><input id="name" v-model="input.name" maxlength="200" :placeholder="t('namePlaceholder')" :class="{ invalid: app.fields.name }" /></div><div class="field"><label for="sku">{{ t('sku') }} <span>{{ t('optional') }}</span></label><input id="sku" v-model="input.sku" maxlength="100" :placeholder="t('skuPlaceholder')" /></div><div class="field span-2"><label for="category">{{ t('category') }}</label><CategorySelect id="category" v-model="input.category" /></div></div><div class="form-divider"></div><h3 class="subsection-heading">{{ t('financials') }}</h3><div class="form-grid"><div v-for="key in moneyFields" :key="key" class="field"><label :for="key">{{ t(key) }}</label><div class="input-unit" :class="{ invalid: localFields[key] }"><span>Rp</span><DecimalInput :id="key" v-model="input[key]" min="0" step="any" /></div><small v-if="key === 'fixed'">{{ t('fixedHint') }}</small><small v-if="localFields[key]" class="negative">{{ localFields[key] }}</small></div><div class="field"><label for="orders">{{ t('orders') }}</label><DecimalInput id="orders" v-model="input.orders" min="1" max="10000000" step="1" :class="{ invalid: localFields.orders }" /></div><div class="field"><label for="targetMargin">{{ t('targetMargin') }}</label><div class="input-unit suffix"><DecimalInput id="targetMargin" v-model="input.targetMargin" min="0" max="100" step="any" /><span>%</span></div></div><div class="field span-2"><label for="notes">{{ t('notes') }}<span>{{ t('optional') }}</span></label><textarea id="notes" v-model="input.notes" maxlength="10000" rows="3" :placeholder="t('notesPlaceholder')"></textarea></div></div></section>
 <RateEditor :input="input" /><button class="btn secondary full" @click="step = 1">{{ t('addMarketEvidence') }}<Icon name="arrow" :size="16" /></button></div>
 <div id="market-inputs" v-show="step === 1" role="tabpanel" aria-labelledby="market-tab"><ResearchFields :input="input" :competitors="competitors" /><section class="panel form-panel"><div class="section-title"><span class="section-icon"><Icon name="image" /></span><div><h3>{{ t('screenshots') }}</h3><p>{{ t('evidenceHint') }}</p><p>{{ t('screenshotsHint') }}</p></div></div><div class="image-grid"><div v-for="im in visibleImages" :key="im.id" class="image-card"><button class="image-preview" :aria-label="im.name" @click="reference = { url: im.url, name: im.name }"><img :src="im.thumbnail" :alt="im.name" /></button><button class="image-delete icon-btn" :aria-label="`${t('remove')} ${im.name}`" @click="removedImages.push(im.id); reference = undefined"><Icon name="close" :size="16" /></button></div><div v-for="(file,i) in files" :key="file.url" class="image-card"><button class="image-preview" :aria-label="file.file.name" @click="reference = { url: file.url, name: file.file.name }"><img :src="file.url" :alt="file.file.name" /></button><button class="image-delete icon-btn" :aria-label="t('remove')" @click="removeFile(i)"><Icon name="close" :size="16" /></button></div><label v-if="files.length + visibleImages.length < 5" class="image-upload"><Icon name="plus" /><span>{{ t('addImages') }}</span><input type="file" accept="image/jpeg,image/png,image/webp" multiple @change="chooseImages" /></label></div><div v-if="reference" class="evidence-reference"><div><strong>{{ reference.name }}</strong><button class="icon-btn" :aria-label="t('close')" @click="reference = undefined"><Icon name="close" /></button></div><img :src="reference.url" :alt="reference.name" /><a :href="reference.url" target="_blank" rel="noopener noreferrer" class="text-link">{{ t('openEvidence') }} ↗</a></div></section></div>
 </div><div id="live-results" class="calculator-results" :aria-busy="!fresh || calculating"><div v-if="!initialized" class="loading-state"><span class="spinner"></span>{{ t('loading') }}</div><div v-else-if="!evaluation" class="panel empty-state"><Icon name="calculator" :size="40" /><p>{{ calculationError }}</p><p v-for="(message,key) in localFields" :key="key">{{ t(key) }}: {{ message }}</p></div><template v-else><p class="live-label"><i></i>{{ t(!fresh || calculating ? 'updatingResults' : 'liveCalc') }}</p><div :class="{ 'results-updating': !fresh || calculating }"><ResearchInsights :evaluation="evaluation" :competitors="competitors" :editable="Boolean(fresh) && !calculating && !saving" @price="input.price = $event" @cost="input.cost = $event" /><Results :evaluation="evaluation" /></div></template></div></div>
 <div class="form-actions research-save"><span class="muted small-text">{{ t('saveResearchHint') }}</span><button class="btn primary" :disabled="saving || calculating || !fresh" @click="save"><Icon name="check" />{{ t(saving ? 'saving' : 'save') }}</button></div><button v-if="app.conflict" class="btn secondary" @click="reloadPage">{{ t('reload') }}</button>
</template>
